package cinema.view.ui;
import java.awt.*;
import javax.swing.*;
import javax.swing.event.*;
public final class ReadOnlyViews {
    private ReadOnlyViews(){}
    private static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    public static JPanel info(JTextArea source,String title){return info(source,title,false);}
    private static JPanel info(JTextArea source,String title,boolean compact){Design.Card card=new Design.Card(new BorderLayout(12,16));JPanel fields=new JPanel(new GridBagLayout());card.add(Design.text(title,"heading"),BorderLayout.NORTH);card.add(new JScrollPane(fields));source.setVisible(false);card.add(source,BorderLayout.SOUTH);Runnable refresh=()->{fields.removeAll();String[] lines=source.getText().split("\\R");int row=0;if(compact){java.util.List<String> priority=java.util.List.of("Phim:","Phòng:","Ghế:","Suất chiếu:","Bắt đầu:","Trạng thái vé:","Thanh toán:","Giá vé:","Mã vé:");java.util.Arrays.sort(lines,java.util.Comparator.comparingInt(line->{for(int i=0;i<priority.size();i++)if(line.startsWith(priority.get(i)))return i;return priority.size();}));}for(String line:lines){if(line.isBlank())continue;int colon=line.indexOf(':');String name=colon<0?"":line.substring(0,colon),value=colon<0?line:line.substring(colon+1).trim();GridBagConstraints c=new GridBagConstraints();c.gridx=compact?(row%2)*2:0;c.gridy=compact?row/2:row;c.weightx=compact?.12:.25;c.fill=GridBagConstraints.HORIZONTAL;c.anchor=GridBagConstraints.NORTHWEST;c.insets=new Insets(8,4,8,16);fields.add(Design.text(name,"subtitle"),c);c.gridx=compact?(row%2)*2+1:1;c.weightx=compact?.38:.75;fields.add(new JLabel("<html>"+escape(value)+"</html>"),c);row++;}if(row==0)fields.add(Design.text("Tra cứu để xem thông tin chi tiết.","subtitle"));GridBagConstraints bottom=new GridBagConstraints();bottom.gridy=compact?(row+1)/2+1:row+1;bottom.weighty=1;fields.add(Box.createVerticalGlue(),bottom);Theme.apply(card);fields.revalidate();fields.repaint();};source.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){refresh.run();}public void removeUpdate(DocumentEvent e){refresh.run();}public void changedUpdate(DocumentEvent e){refresh.run();}});refresh.run();return card;}
    public static JPanel profile(JTable source){JTextArea data=new JTextArea();JPanel card=info(data,"Thông tin cá nhân");source.setVisible(false);card.add(source,BorderLayout.EAST);Runnable refresh=()->{if(source.getRowCount()==0){data.setText("");return;}StringBuilder text=new StringBuilder();for(int col=0;col<source.getColumnCount();col++)text.append(source.getColumnName(col)).append(": ").append(source.getValueAt(0,col)==null?"—":source.getValueAt(0,col)).append('\n');data.setText(text.toString());};source.getModel().addTableModelListener(e->refresh.run());refresh.run();return card;}
    public static final class Gate extends JPanel {
        private final JLabel heading=Design.text("SẴN SÀNG SOÁT VÉ","title"),explanation=Design.text("Chọn đúng phòng/suất, sau đó nhập mã vé hoặc đọc ảnh QR.","subtitle");private final JPanel banner=Design.stack(heading,explanation);private String color="info";
        public Gate(JTextArea source,JLabel status){super(new BorderLayout(16,16));banner.setBorder(BorderFactory.createEmptyBorder(16,20,16,20));add(banner,BorderLayout.NORTH);add(info(source,"Thông tin vé",true));status.addPropertyChangeListener("text",e->update(status.getText()));update(status.getText());}
        private void update(String text){String value=text==null?"":text;color="info";String title="SẴN SÀNG SOÁT VÉ";if(value.equals("Vé hợp lệ")){title="HỢP LỆ";color="success";}else if(value.equals("Vé đã được sử dụng")||value.equals("Xác nhận vé thành công")){title="ĐÃ SỬ DỤNG";color="info";}else if(value.equals("Vé chưa có thanh toán hợp lệ")){title="CHƯA THANH TOÁN";color="warning";}else if(value.equals("Vé không đúng suất chiếu đang kiểm soát")){title="SAI SUẤT CHIẾU";color="danger";}else if(value.equals("Vé không đúng phòng đang kiểm soát")){title="SAI PHÒNG CHIẾU";color="danger";}else if(value.equals("Vé không tồn tại")){title="VÉ KHÔNG TỒN TẠI";color="danger";}else if(value.contains("không hợp lệ")||value.contains("Ngoài thời gian")||value.contains("đã bị hủy")){title="CẦN KIỂM TRA LẠI";color="danger";}else if(value.startsWith("Đang"))title="ĐANG KIỂM TRA";else if(value.startsWith("Đã tra cứu"))title="ĐÃ TÌM THẤY VÉ";heading.setText(title);heading.setIcon(new Icons(color.equals("success")?"check":color.equals("info")?"ticket":"alert",28));heading.setIconTextGap(16);explanation.setText(value);repaint();}
        @Override protected void paintComponent(Graphics g){super.paintComponent(g);Color tone=switch(color){case "success"->Theme.success();case "warning"->Theme.warning();case "danger"->Theme.danger();default->Theme.info();};banner.setBackground(Theme.tone(tone));heading.setForeground(tone);}
    }
}
